import pandas as pd
import numpy as np
from solver import Algorithm
from typing import Tuple, List


class Evolved(Algorithm):
    """Optimize row serialization prefixes while preserving every original cell."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe for compatibility with the base API."""
        self.df = df

    @staticmethod
    def _string_matrix(df: pd.DataFrame) -> np.ndarray:
        """Build evaluator-compatible strings without changing the stored dataframe."""
        safe = df.astype(object).where(pd.notna(df), "")
        return safe.astype(str).to_numpy(dtype=object, copy=False)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute an LCP with C-level slice comparisons and binary search."""
        limit = min(len(left), len(right))
        if limit == 0:
            return 0
        if left == right:
            return limit

        low, high = 0, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    def _serial_score(self, strings: np.ndarray, orders) -> int:
        """Measure exact ideal character-Trie reuse through sorted serialized rows."""
        n_rows = strings.shape[0]
        if n_rows < 2:
            return 0

        if isinstance(orders, tuple):
            positions = list(orders)
            serial = ["".join(strings[row, positions]) for row in range(n_rows)]
        else:
            serial = [
                "".join(strings[row, list(orders[row])])
                for row in range(n_rows)
            ]

        serial.sort()
        return sum(
            self._lcp(serial[i - 1], serial[i])
            for i in range(1, n_rows)
        )

    @staticmethod
    def _column_statistics(strings: np.ndarray):
        """Compute repetition and prefix-aware savings estimates for each column."""
        n_rows, n_cols = strings.shape
        strong = np.zeros(n_cols, dtype=np.int64)
        prefix = np.zeros(n_cols, dtype=np.int64)
        codes = []
        lengths = []

        for col in range(n_cols):
            values = strings[:, col]
            code, unique = pd.factorize(values, sort=False)
            code = np.asarray(code, dtype=np.int64)
            unique = [str(value) for value in unique]

            counts = np.bincount(code, minlength=len(unique)).astype(np.int64)
            value_lengths = np.asarray(
                [len(value) for value in unique],
                dtype=np.int64,
            )

            # Required length-weighted pair repetition heuristic.
            strong[col] = int(
                np.sum(value_lengths * counts * (counts - 1))
            )

            # Prefix-aware alternative: repeated identical values plus common
            # prefixes among lexicographically adjacent distinct serialized values.
            repeated = int(np.sum(value_lengths * np.maximum(counts - 1, 0)))
            ordered_unique = sorted(unique)
            common = 0
            for i in range(1, len(ordered_unique)):
                common += Evolved._lcp(
                    ordered_unique[i - 1],
                    ordered_unique[i],
                )
            prefix[col] = repeated + common

            codes.append(code)
            lengths.append(value_lengths)

        return strong, prefix, codes, lengths

    @staticmethod
    def _constrained_order(
        base_order: List[int],
        columns: List,
        col_merge: List[List[str]],
        one_way_dep: List[Tuple[str, str]],
    ) -> List[int]:
        """Apply merge blocks and dependency precedence to a proposed global order."""
        n_cols = len(columns)
        if n_cols <= 1 or (not col_merge and not one_way_dep):
            return list(base_order)

        positions_by_name = {}
        for position, name in enumerate(columns):
            positions_by_name.setdefault(name, []).append(position)

        parent = list(range(n_cols))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            root_a = find(a)
            root_b = find(b)
            if root_a != root_b:
                parent[root_b] = root_a

        # Overlapping merge groups are treated as one larger adjacency block.
        for group in col_merge or []:
            members = []
            for name in group:
                members.extend(positions_by_name.get(name, []))
            if len(members) > 1:
                first = members[0]
                for member in members[1:]:
                    union(first, member)

        components = {}
        for position in range(n_cols):
            components.setdefault(find(position), []).append(position)

        rank_of_position = {
            position: rank for rank, position in enumerate(base_order)
        }
        blocks = list(components.values())
        for block in blocks:
            block.sort(key=lambda p: rank_of_position[p])

        block_of = {}
        for block_id, block in enumerate(blocks):
            for position in block:
                block_of[position] = block_id

        rank = {
            block_id: min(rank_of_position[p] for p in block)
            for block_id, block in enumerate(blocks)
        }

        outgoing = [[] for _ in blocks]
        indegree = [0] * len(blocks)
        edges = set()

        for source_name, target_name in one_way_dep or []:
            for source in positions_by_name.get(source_name, []):
                for target in positions_by_name.get(target_name, []):
                    source_block = block_of[source]
                    target_block = block_of[target]
                    if source_block != target_block:
                        edges.add((source_block, target_block))

        for source_block, target_block in edges:
            outgoing[source_block].append(target_block)
            indegree[target_block] += 1

        ready = sorted(
            [i for i in range(len(blocks)) if indegree[i] == 0],
            key=lambda b: rank[b],
        )
        result_blocks = []

        while ready:
            block = ready.pop(0)
            result_blocks.append(block)
            for target in outgoing[block]:
                indegree[target] -= 1
                if indegree[target] == 0:
                    ready.append(target)
                    ready.sort(key=lambda b: rank[b])

        # Cyclic dependency specifications cannot all be honored; retain
        # deterministic base-order placement for unresolved blocks.
        if len(result_blocks) != len(blocks):
            seen = set(result_blocks)
            result_blocks.extend(
                block
                for block in sorted(range(len(blocks)), key=lambda b: rank[b])
                if block not in seen
            )

        return [
            position
            for block in result_blocks
            for position in blocks[block]
        ]

    @staticmethod
    def _conditional_orders(
        codes,
        lengths,
        default_order: Tuple[int, ...],
        n_rows: int,
        depth_limit: int,
    ) -> List[Tuple[int, ...]]:
        """Create bounded row-specific orders by recursively partitioning repeated values."""
        n_cols = len(default_order)
        candidate_cols = tuple(default_order[: min(n_cols, 32)])
        orders = [None] * n_rows

        max_nodes = 320
        nodes = 0
        stack = [
            (
                np.arange(n_rows, dtype=np.int64),
                tuple(),
                candidate_cols,
                0,
            )
        ]

        while stack:
            rows, prefix, remaining, depth = stack.pop()
            nodes += 1

            if (
                len(rows) < 2
                or not remaining
                or depth >= depth_limit
                or nodes > max_nodes
            ):
                tail = tuple(col for col in default_order if col not in prefix)
                final_order = prefix + tail
                for row in rows:
                    orders[int(row)] = final_order
                continue

            best_col = None
            best_score = 0

            for col in remaining:
                row_codes = codes[col][rows]
                counts = np.bincount(
                    row_codes,
                    minlength=len(lengths[col]),
                ).astype(np.int64)
                score = int(
                    np.sum(lengths[col] * counts * (counts - 1))
                )

                if (
                    score > best_score
                    or (
                        score == best_score
                        and best_col is not None
                        and col < best_col
                    )
                ):
                    best_score = score
                    best_col = col

            if best_col is None or best_score <= 0:
                tail = tuple(col for col in default_order if col not in prefix)
                final_order = prefix + tail
                for row in rows:
                    orders[int(row)] = final_order
                continue

            selected_codes = codes[best_col][rows]
            order = np.argsort(selected_codes, kind="stable")
            sorted_rows = rows[order]
            sorted_codes = selected_codes[order]

            next_remaining = tuple(
                col for col in remaining if col != best_col
            )

            start = 0
            while start < len(sorted_rows):
                end = start + 1
                while (
                    end < len(sorted_rows)
                    and sorted_codes[end] == sorted_codes[start]
                ):
                    end += 1

                stack.append(
                    (
                        sorted_rows[start:end],
                        prefix + (best_col,),
                        next_remaining,
                        depth + 1,
                    )
                )
                start = end

        fallback = tuple(default_order)
        return [
            order if order is not None else fallback
            for order in orders
        ]

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the best bounded serialization layout while preserving all cells."""
        n_rows, n_cols = df.shape
        columns = list(df.columns)

        if n_rows == 0 or n_cols == 0:
            return df.copy(), [[] for _ in range(n_rows)]

        strings = self._string_matrix(df)
        strong, prefix, codes, lengths = self._column_statistics(strings)

        original = list(range(n_cols))
        frequency_order = sorted(
            original,
            key=lambda col: (-int(strong[col]), col),
        )
        prefix_order = sorted(
            original,
            key=lambda col: (
                -int(prefix[col]),
                -int(strong[col]),
                col,
            ),
        )

        frequency_order = self._constrained_order(
            frequency_order,
            columns,
            col_merge,
            one_way_dep,
        )
        prefix_order = self._constrained_order(
            prefix_order,
            columns,
            col_merge,
            one_way_dep,
        )

        candidates = [tuple(frequency_order)]
        if tuple(prefix_order) != tuple(frequency_order):
            candidates.append(tuple(prefix_order))

        # Conditional row-specific layouts are only used where their bounded
        # construction cost remains small and explicit global constraints are absent.
        cell_count = n_rows * n_cols
        if (
            not col_merge
            and not one_way_dep
            and cell_count <= 1_000_000
            and n_cols <= 128
        ):
            depth_limit = min(
                8,
                n_cols,
                col_stop if col_stop is not None and col_stop > 0 else 8,
            )
            candidates.append(
                self._conditional_orders(
                    codes,
                    lengths,
                    tuple(frequency_order),
                    n_rows,
                    depth_limit,
                )
            )

        total_chars = sum(len(value) for value in strings.ravel())

        # Exact objective selection is bounded to avoid long-tail runtime loss.
        if total_chars <= 15_000_000:
            best = max(
                candidates,
                key=lambda candidate: self._serial_score(strings, candidate),
            )
        else:
            best = candidates[0]

        source = df.to_numpy(dtype=object, copy=True)

        if isinstance(best, tuple):
            positions = list(best)
            output = source[:, positions]
            row_orders = [best] * n_rows
        else:
            output = np.empty(source.shape, dtype=object)
            for row, order in enumerate(best):
                output[row, :] = source[row, list(order)]
            row_orders = best

        reordered = pd.DataFrame(
            output,
            index=df.index.copy(),
            columns=df.columns.copy(),
            dtype=object,
        )

        column_orderings = [
            [columns[position] for position in order]
            for order in row_orders
        ]

        return reordered, column_orderings

